void solve() {
    int m, d;
    cin >> m >> d;
    vector<int> a(m + 1, LLONG_MIN);
    SegTree seg;
    seg.build(a);
    int len = 0, last = 0;
    while (m--) {
        char op;
        int x;
        cin >> op >> x;
        if (op == 'A') {
            int v = ((__int128)x + last) % d;
            if (v < 0)
                v += d;
            seg.change(++len, v);
        } else {
            last = seg.qur(len - x + 1, len).mn;
            cout << last << '\n';
        }
    }
}

