struct DSU {
    vector<int> fid, sz;
    DSU(int n = 0) {
        init(n);
    }
    void init(int n) {
        fid.resize(n + 1);
        iota(fid.begin(), fid.end(), 0);
        sz.assign(n + 1, 1);
    }
    int root(int x) {
        return fid[x] == x ? x : fid[x] = root(fid[x]);
    }
    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y)
            return false;
        if (sz[x] > sz[y])
            swap(x, y);
        fid[x] = y;
        sz[y] += sz[x];
        return true;
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    int size(int x) {
        return sz[root(x)];
    }
};

