            seg[id].lc = t;
        } else {
            int t = change(rs(id), mid + 1, r, pos, v);
            seg[id].rc = t;
        }
        update(id);
        return id;
    }

    void change(int pos, const info &v) {
        assert(L <= pos && pos <= R && v.cnt != 0);
        assert((__int128)size() + v.cnt >= 0);
        assert((__int128)size() + v.cnt <= LLONG_MAX);
