void solve() {
    int q;
    cin >> q;
    WeightSegTree seg(0, 1000000000);
    while (q--) {
        int op;
        cin >> op;
        if (op == 1) {
            int x;
            cin >> x;
            seg.change(x, {1});
        } else if (op == 2) {
            int x, c;
            cin >> x >> c;
            int del = min(c, seg.qur(x, x).cnt);
            if (del)
                seg.change(x, {-del}); // 没有该元素时不调用 change(x,{0})
        } else {
            // 原题保证此时非空；重复元素会占据多个排名。
            cout << seg.kth_max(1) - seg.kth(1) << '\n';
        }
    }
}

