                cout << a[seg.kth(cnt - k + 1) - 1] << '\n';
        } else {
            int cnt = seg.qur(1, pos - 1).cnt;
            if (seg.size() - cnt < k)
                cout << -1 << '\n';
            else
                cout << a[seg.kth(cnt + k) - 1] << '\n';
        }
    }
}

