void solve() {
    int n, m;
    cin >> n >> m;
    DSU dsu(n);
    WeightSegForest seg(1, n);
    vector<int> root(n + 1), id(n + 1);
    for (int i = 1, x; i <= n; i++) {
        cin >> x;
        id[x] = i;
        root[i] = seg.change(0, x, 1);
    }
    auto join = [&](int x, int y) {
        x = dsu.root(x);
        y = dsu.root(y);
        if (x == y)
            return;
        int r = seg.merge(root[x], root[y]);
        root[x] = root[y] = 0;
        dsu.merge(x, y);
        root[dsu.root(x)] = r;
    };
    while (m--) {
        int u, v;
        cin >> u >> v;
        join(u, v);
    }
    int q;
    cin >> q;
    while (q--) {
        char op;
        int x, y;
        cin >> op >> x >> y;
        if (op == 'B')
            join(x, y);
        else {
            int r = root[dsu.root(x)];
            if (y > seg.size(r))
                cout << -1 << '\n';
            else
                cout << id[seg.kth(r, seg.size(r) - y + 1)] << '\n';
        }
    }
}

