        vector<bool> vis(tot + 1);

        priority_queue<pii, vector<pii>, greater<pii>> pq;

        dis[s] = 0;
        pq.push({0, s});

        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();

            if (vis[u])
                continue;
            vis[u] = true;

            for (auto [v, w] : adj[u]) {
                if (dis[v] > d + w) {
                    dis[v] = d + w;
                    pq.push({dis[v], v});
                }
            }
        }

        return dis;
    }
};

void solve() {
    int n, q, s;
    cin >> n >> q >> s;
    SegGraph sg(n);
    while (q--) {
        int op, v, l, r, w;
        cin >> op;
        if (op == 1) {
            cin >> v >> l >> w;
            sg.add_edge(v, l, w);
        } else {
            cin >> v >> l >> r >> w;
            if (op == 2)
                sg.add_out(v, l, r, w);
            else
                sg.add_in(l, r, v, w);
        }
    }
    auto d = sg.dijkstra(s);
    for (int i = 1; i <= n; i++)
        cout << (d[i] == INF ? -1 : d[i]) << (i == n ? '\n' : ' ');
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t = 1;
    // cin >> t;
    while (t--)
        solve();
    return 0;
}

