struct HK {
    int n1, n2, shortest;
    vector<vector<int>> e;
    vector<int> ml, mr, dis, cur;

    void init(int _n1, int _n2) {
        n1 = _n1;
        n2 = _n2;
        e.assign(n1 + 1, {});
        ml.assign(n1 + 1, 0);
        mr.assign(n2 + 1, 0);
        dis.assign(n1 + 1, -1);
        cur.assign(n1 + 1, 0);
    }

    // 添加原图的边：左部 u -> 右部 v。
    void add(int u, int v) {
        e[u].push_back(v);
    }

    // 分层：从所有未匹配的左部点同时出发，求最短增广路长度。
    bool bfs() {
        queue<int> q;
        fill(dis.begin(), dis.end(), -1);
        shortest = LLONG_MAX;

        for (int i = 1; i <= n1; i++) {
            if (!ml[i]) {
                dis[i] = 0;
                q.push(i);
            }
        }

