struct BipColor {
    int n;
    vector<vector<int>> e;
    vector<int> col;
    vector<array<int, 2>> cnt;
    void init(int n_) {
        n = n_;
        e.assign(n + 1, {});
        col.assign(n + 1, -1);
        cnt.clear();
    }
    void addedge(int u, int v) {
        e[u].push_back(v);
        e[v].push_back(u);
    }
    bool dfs(int u, int c, array<int, 2> &num) {
        col[u] = c;
        num[c]++;
        for (int v : e[u]) {
            if (col[v] == -1) {
                if (!dfs(v, c ^ 1, num))
                    return false;
            } else if (col[v] == c)
                return false;
        }
        return true;
    }
    bool run() {
        fill(col.begin(), col.end(), -1);
        cnt.clear();
        for (int u = 1; u <= n; u++)
            if (col[u] == -1) {
                array<int, 2> num = {0, 0};
                if (!dfs(u, 0, num))
                    return false;
                cnt.push_back(num);
            }
        return true;
    }
};

