        LOG = 1;
        while ((1LL << LOG) <= n)
            LOG++;
        e.assign(n + 1, {});
        fa.assign(LOG, vector<int>(n + 1));
        dep.assign(n + 1, 0);
    }
    void addedge(int u, int v) {
        e[u].push_back(v);
        e[v].push_back(u);
