    void dfs(int u, int f) {
        fa[0][u] = f;
        dep[u] = dep[f] + 1;
        for (int j = 1; j < LOG; j++)
            fa[j][u] = fa[j - 1][fa[j - 1][u]];
        for (int v : e[u])
            if (v != f)
                dfs(v, u);
