        if (dep[u] < dep[v])
            swap(u, v);
        int d = dep[u] - dep[v];
        for (int j = 0; j < LOG; j++)
            if (d >> j & 1)
                u = fa[j][u];
        if (u == v)
            return u;
        for (int j = LOG - 1; j >= 0; j--)
            if (fa[j][u] != fa[j][v]) {
                u = fa[j][u];
                v = fa[j][v];
            }
        return fa[0][u];
    }
