        tr.assign(2 * n + 1, {});
        dep.assign(2 * n + 1, 0);
        bel.assign(2 * n + 1, 0);
        LOG = 1;
        while ((1LL << LOG) <= 2 * n)
            LOG++;
        up.assign(LOG, vector<int>(2 * n + 1));
    }
    int find(int x) {
        return fa[x] == x ? x : fa[x] = find(fa[x]);
    }
