        dep[u] = dep[f] + 1;
        bel[u] = component;
        for (int j = 1; j < LOG; j++)
            up[j][u] = up[j - 1][up[j - 1][u]];
        for (int v : tr[u])
            dfs(v, u, component);
    }
    void build(bool maximum = false) {
        sort(e.begin(), e.end(),
             [&](edge a, edge b) { return maximum ? a.w > b.w : a.w < b.w; });
        for (auto [u, v, w] : e) {
            int x = find(u), y = find(v);
            if (x == y)
                continue;
            ++tot;
            val[tot] = w;
            tr[tot] = {x, y};
            fa[x] = fa[y] = tot;
        }
        for (int u = 1; u <= tot; u++)
            if (fa[u] == u)
                dfs(u, 0, u);
    }
    int lca(int u, int v) {
        if (bel[u] != bel[v])
            return 0;
        if (dep[u] < dep[v])
            swap(u, v);
        int d = dep[u] - dep[v];
        for (int j = 0; j < LOG; j++)
            if (d >> j & 1)
