void solve() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    Kosaraju scc;
    scc.init(n);
    vector<pair<int, int>> e(m);
    for (auto &[u, v] : e) {
        cin >> u >> v;
        scc.addedge(u, v);
    }
    scc.run();
    int k = scc.cnt;
    vector<int> w(k + 1), deg(k + 1);
    vector<vector<int>> g(k + 1);
    for (int i = 1; i <= n; i++)
        w[scc.bel[i]] += a[i];
    for (auto [u, v] : e) {
        u = scc.bel[u];
        v = scc.bel[v];
        if (u != v) {
            g[u].push_back(v);
            deg[v]++;
        }
    }
    queue<int> q;
    vector<int> dp = w;
    for (int c = 1; c <= k; c++)
        if (!deg[c])
            q.push(c);
    int ans = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        ans = max(ans, dp[u]);
        for (int v : g[u]) {
            dp[v] = max(dp[v], dp[u] + w[v]);
            if (!--deg[v])
                q.push(v);
        }
    }
    cout << ans << '\n';
}

