void solve() {
    int m, tc = 0;
    while (cin >> m && m) {
        vector<pair<int, int>> e(m);
        int n = 0;
        for (auto &[u, v] : e) {
            cin >> u >> v;
            n = max(n, max(u, v));
        }
        VDCC g;
        g.init(n);
        vector<int> present(n + 1);
        for (int i = 0; i < m; i++) {
            auto [u, v] = e[i];
            present[u] = present[v] = 1;
            g.addedge(u, v, i);
        }
        g.run();
        int need = 0;
        unsigned long long ways = 1;
        for (auto &c : g.bcc) {
            if (!present[c[0]])
                continue;
            int cuts = 0;
            for (int u : c)
                cuts += g.cut[u];
            int s = c.size();
            if (cuts == 0) {
                need += 2;
                ways *= 1ULL * s * (s - 1) / 2;
            } else if (cuts == 1) {
                need++;
                ways *= s - 1;
            }
        }
        cout << "Case " << ++tc << ": " << need << ' ' << ways << '\n';
    }
}

