void solve() {
    int k, n;
    cin >> k >> n;
    int s = k + n + 1, t = s + 1;
    FlowGraph<int> g;
    g.init(s, t, t);
    int need = 0;
    for (int c = 1, x; c <= k; c++) {
        cin >> x;
        need += x;
        g.addedge(s, c, x);
    }
    vector<array<int, 3>> chosen;
    for (int j = 1; j <= n; j++) {
        int p;
        cin >> p;
        while (p--) {
            int c;
            cin >> c;
            chosen.push_back({c, j, g.etot});
            g.addedge(c, k + j, 1);
        }
        g.addedge(k + j, t, 1);
    }
    if (g.dinic() != need) {
        cout << "No Solution!\n";
        return;
    }
    vector<vector<int>> ans(k + 1);
    for (auto [c, j, id] : chosen)
        if (g.e[id].f == 0)
            ans[c].push_back(j);
    for (int c = 1; c <= k; c++) {
        cout << c << ":";
        for (int j : ans[c])
            cout << ' ' << j;
        cout << '\n';
    }
}

