void solve() {
    int n;
    cin >> n;
    vector<array<int, 3>> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i][0] >> a[i][1];
        a[i][2] = i + 1;
    }
    Prim g;
    g.init(n);
    for (int dim = 0; dim < 2; dim++) {
        sort(a.begin(), a.end(), [&](auto x, auto y) { return x[dim] < y[dim]; });
        for (int i = 1; i < n; i++)
            g.addedge(a[i - 1][2], a[i][2],
                      min(llabs(a[i][0] - a[i - 1][0]), llabs(a[i][1] - a[i - 1][1])));
    }
    cout << g.run().second << '\n';
}

