struct Topo {
    int n;
    vector<vector<int>> edge;
    vector<int> d;
    void init(int n_) {
        n = n_;
        edge.assign(n + 1, {});
        d.assign(n + 1, 0);
    }
    void addedge(int u, int v) {
        edge[u].push_back(v);
        d[v]++;
    }
    vector<int> toposort(bool lex = false) {
        vector<int> deg = d, res;
        queue<int> q;
        priority_queue<int, vector<int>, greater<int>> pq;
        for (int i = 1; i <= n; i++)
            if (!deg[i]) {
                if (lex)
                    pq.push(i);
                else
                    q.push(i);
            }
        while (lex ? !pq.empty() : !q.empty()) {
            int u;
            if (lex) {
                u = pq.top();
                pq.pop();
            } else {
                u = q.front();
                q.pop();
            }
            res.push_back(u);
            for (int v : edge[u])
                if (!--deg[v]) {
                    if (lex)
                        pq.push(v);
                    else
                        q.push(v);
                }
        }
        return res;
    }
};

