struct Euler {
    int n, m;
    vector<vector<int>> adj;
    vector<int> in, out, path;
    void init(int n_) {
        n = n_;
        m = 0;
        adj.assign(n + 1, {});
        in.assign(n + 1, 0);
        out = in;
        path.clear();
    }
    void addedge(int u, int v) {
        adj[u].push_back(v);
        out[u]++;
        in[v]++;
        m++;
    }
    void dfs(int u) {
        while (!adj[u].empty()) {
            int v = adj[u].back();
            adj[u].pop_back();
            dfs(v);
        }
        path.push_back(u);
    }
    bool run(bool lex = true) {
        int st = 0, en = 0;
        for (int u = 1; u <= n; u++) {
            int d = out[u] - in[u];
            if (d == 1) {
                if (st)
                    return false;
                st = u;
            } else if (d == -1) {
                if (en)
                    return false;
                en = u;
            } else if (d)
                return false;
        }
        if (bool(st) != bool(en))
            return false;
        if (!st)
            for (int u = 1; u <= n; u++)
                if (out[u]) {
                    st = u;
                    break;
                }
        if (!st)
            st = 1;
        if (lex)
            for (int u = 1; u <= n; u++)
                sort(adj[u].begin(), adj[u].end(), greater<int>());
        path.clear();
        dfs(st);
        reverse(path.begin(), path.end());
        return (int)path.size() == m + 1;
    }
};

