struct Difference {
    struct edge {
        int u, v, w;
    };
    int n;
    vector<edge> e;
    vector<int> x;
    void init(int n_) {
        n = n_;
        e.clear();
        x.assign(n + 1, 0);
    }
    // 加入x[v]-x[u]<=w，未知数1..n。
    void add_constraint(int u, int v, int w) {
        e.push_back({u, v, w});
    }
    bool solve() {
        fill(x.begin(), x.end(), 0);
        for (int i = 1; i <= n; i++) {
            bool changed = false;
            for (auto [u, v, w] : e)
                if (x[v] > x[u] + w) {
                    x[v] = x[u] + w;
                    changed = true;
                    if (i == n)
                        return false;
                }
            if (!changed)
                return true;
        }
        return true;
    }
    // 特例：所有w<=0；求a[i]>=1且a[v]>=a[u]-w的最小解，x=-a。
    bool minimum_positive() {
