        auto itr = split(r + 1), itl = split(l);
        int ans = 0;
        for (; itl != itr; ++itl)
            ans = (ans + (__int128)(itl->r - itl->l + 1) * powmod(itl->v, k, p)) % p;
        return ans;
    }
