void solve() {
    int n, m, seed, vmax;
    cin >> n >> m >> seed >> vmax;
    auto rnd = [&]() {
        int ret = seed;
        seed = (seed * 7 + 13) % 1000000007;
        return ret;
    };
    ODT t(n);
    for (int i = 1; i <= n; i++)
        t.assign(i, i, rnd() % vmax + 1);
    for (int i = 0; i < m; i++) {
        int op = rnd() % 4 + 1, l = rnd() % n + 1, r = rnd() % n + 1;
        if (l > r)
            swap(l, r);
        int x = op == 3 ? rnd() % (r - l + 1) + 1 : rnd() % vmax + 1;
        if (op == 1)
            t.add(l, r, x);
        if (op == 2)
            t.assign(l, r, x);
        if (op == 3)
            cout << t.kth(l, r, x) << '\n';
        if (op == 4) {
            int y = rnd() % vmax + 1;
            cout << t.qur(l, r, x, y) << '\n';
        }
    }
}

