        for (int p : pos[u]) {
            if (p > 1)
                segments -= (a[p] != a[p - 1]);
            if (p < n)
                segments -= (a[p] != a[p + 1]);
            a[p] = v;
            if (p > 1)
                segments += (a[p] != a[p - 1]);
            if (p < n)
                segments += (a[p] != a[p + 1]);
            pos[v].push_back(p);
        }
        vector<int>().swap(pos[u]);
    }
    // 另一种容器：小map并入大map，维护最大出现次数的颜色编号和。
    struct info {
        map<int, int> cnt;
        int mx = 0, sum = 0;
    };
    static void insert(info &s, int c, int k) {
        int x = (s.cnt[c] += k);
        if (x > s.mx)
            s.mx = x, s.sum = c;
        else if (x == s.mx)
            s.sum += c;
    }
    static void merge(info &a, info &b) {
        if (a.cnt.size() < b.cnt.size())
            swap(a, b);
        for (auto [c, k] : b.cnt)
            insert(a, c, k);
        b = info();
    }
};

