                if (!p[i]) {
                    p[i] = x;
                    return true;
                }
                x ^= p[i];
            }
        zero = true;
        return false;
    }
    bool exist(int x) {
        for (int i = B; i >= 0; i--)
            if ((x >> i) & 1)
                x ^= p[i];
        return x == 0;
    }
    int qur(int x = 0) {
        for (int i = B; i >= 0; i--)
            x = max(x, x ^ p[i]);
        return x;
    }
    int rank() {
        int ans = 0;
        for (int x : p)
            ans += x != 0;
        return ans;
    }
