                        b[j] ^= b[i];
        vector<int> a;
        for (int x : b)
            if (x)
                a.push_back(x);
        // nonempty: k为1基；有非空零组合时，第1小为0。
        if (nonempty) {
            if (!k)
                return nullopt;
            if (zero)
                --k;
        }
        if (k >= (1ULL << a.size()))
            return nullopt;
        int ans = 0;
        for (int i = 0; i < (int)a.size(); i++)
