            for (int k = l; k < r; k++) {
                int val = dp[l][k] + dp[k + 1][r] + s[r] - s[l - 1];
                if (maximum)
                    dp[l][r] = max(dp[l][r], val);
                else
                    dp[l][r] = min(dp[l][r], val);
            }
        }
    int ans = maximum ? -INF : INF;
    for (int l = 1; l <= (circle ? n : 1); l++)
        if (maximum)
            ans = max(ans, dp[l][l + n - 1]);
        else
            ans = min(ans, dp[l][l + n - 1]);
    return ans;
