                    dp[l][r] = max(dp[l][r], dp[l + 1][x - 1] + dp[x][r] + 1);
            }
    }
    int clear_min() {
        int n = a.size() - 1;
        return n - dp[1][n];
    }
    int uniform_min() {
        return max(0LL, clear_min() - 1);
    }
};

