struct TreeMaxSum {
    int n;
    vector<vector<int>> son;
    vector<int> a, f, ans;
    TreeMaxSum(int n = 0) {
        init(n);
    }
    void init(int n_) {
        n = n_;
        son.assign(n + 1, {});
        a.assign(n + 1, 0);
        f = ans = a;
    }
    void add_edge(int u, int v) {
        son[u].push_back(v);
        son[v].push_back(u);
    }
    void dfs(int u, int p) {
        f[u] = a[u];
        for (int v : son[u])
            if (v != p) {
                dfs(v, u);
                f[u] += max(0LL, f[v]);
            }
    }
    void dfs2(int u, int p, int up) {
