            int u = q.front();
            q.pop();
            for (int i = head[u]; i != -1; i = e[i].nxt)
                if (e[i].f > 0 && !vis[e[i].v]) {
                    vis[e[i].v] = 1;
                    q.push(e[i].v);
                }
        }
        return vis;
    }
};
struct BoundedFlow {
    static constexpr int INF = 4000000000000000000LL;
    struct edge {
        int u, v, l, r, id;
    };
    int n, S, T;
    vector<int> balance;
    vector<edge> edges;
    FlowGraph<int> g;
    vector<int> aux;
    BoundedFlow(int n = 0) {
        init(n);
    }
    void init(int n_) {
        n = n_;
        S = n + 1;
        T = n + 2;
        balance.assign(n + 1, 0);
        edges.clear();
        aux.clear();
        g.init(S, T, T);
    }
    int add_edge(int u, int v, int l, int r) {
        assert(0 <= l && l <= r);
        int id = g.etot;
        g.addedge(u, v, r - l);
        balance[u] -= l;
        balance[v] += l;
        edges.push_back({u, v, l, r, id});
        return edges.size() - 1;
    }
    bool feasible() {
        int need = 0;
        for (int u = 1; u <= n; u++) {
            if (balance[u] > 0) {
                aux.push_back(g.etot);
                g.addedge(S, u, balance[u]);
                need += balance[u];
            }
            if (balance[u] < 0) {
                aux.push_back(g.etot);
                g.addedge(u, T, -balance[u]);
            }
        }
        return g.dinic() == need;
    }
    int value(int k) {
        auto z = edges[k];
        return z.r - g.e[z.id].f;
    }
    optional<int> maxflow(int s, int t) {
        int back = g.etot;
        g.addedge(t, s, INF);
        if (!feasible())
            return nullopt;
        int base = g.e[back ^ 1].f;
        g.e[back].f = g.e[back ^ 1].f = 0;
        for (int id : aux)
            g.e[id].f = g.e[id ^ 1].f = 0;
        g.s = s;
        g.t = t;
        return base + g.dinic();
    }
};

void solve() {
    int n;
    cin >> n;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    int s = n + 1, t = n + 2;
    BoundedFlow g(t);
    vector<array<int, 3>> choice;
    auto prime = [](int x) {
        if (x < 2)
            return false;
        for (int p = 2; p <= x / p; p++)
            if (x % p == 0)
                return false;
        return true;
    };
    for (int i = 1; i <= n; i++)
        if (a[i] & 1)
            g.add_edge(s, i, 2, 2);
        else
            g.add_edge(i, t, 2, 2);
    for (int i = 1; i <= n; i++)
        if (a[i] & 1)
            for (int j = 1; j <= n; j++)
                if (!(a[j] & 1) && prime(a[i] + a[j]))
                    choice.push_back({i, j, g.add_edge(i, j, 0, 1)});
    g.add_edge(t, s, 0, 2 * n);
    if (!g.feasible()) {
        cout << "Impossible\n";
        return;
    }
    vector<vector<int>> adj(n + 1), cycles;
    for (auto [u, v, k] : choice)
        if (g.value(k))
            adj[u].push_back(v), adj[v].push_back(u);
    vector<int> vis(n + 1);
    for (int i = 1; i <= n; i++)
        if (!vis[i]) {
            vector<int> cyc;
            int u = i, p = 0;
            do {
                cyc.push_back(u);
                vis[u] = 1;
                int v = adj[u][0] == p ? adj[u][1] : adj[u][0];
                p = u;
                u = v;
            } while (u != i);
            cycles.push_back(cyc);
        }
    cout << cycles.size() << '\n';
    for (auto c : cycles) {
        cout << c.size();
        for (int u : c)
            cout << ' ' << u;
        cout << '\n';
    }
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t = 1;
    // cin >> t;
    while (t--)
        solve();
    return 0;
}

