    // 作用：按分层图多路增广；前提bfs成功，cur已重置；一轮阻塞流一般O(VE)。
    T dfs(int u, T m) {
        if (u == t)
            return m;
        T flow = 0; // 本次从u成功送出的总量，0..初始m。
        for (int i = cur[u]; i != -1; cur[u] = i = e[i].nxt) {
            // i：当前弧；保留PPT的cur推进方式，送满本次额度时不前移。
            if (e[i].f > 0 && dis[e[i].v] == dis[u] + 1) {
                T f = dfs(e[i].v, min(m, e[i].f)); // 实际成功增广量，0..min(m,残量)。
                e[i].f -= f;
                e[i ^ 1].f += f;
                m -= f;
                flow += f;
                if (m == 0)
                    break;
            }
        }
        if (flow == 0)
            dis[u] = -1;
        return flow;
    }
    // dinic()：无参数；返回本次新增最大流T；作用：反复分层并求阻塞流。
    // 前提合法源汇、图已建好、总流量不溢出；一般时间O(Vnet²*Enet)，空间O(Vnet+Enet)，额外递归栈O(Vnet)。
    T dinic() {
        T flow = 0; // 本次调用新增流量，init后首次调用即总最大流。
        while (bfs())
            flow += dfs(s, numeric_limits<T>::max());
        return flow;
    }
    vector<int> cut_side() {
        vector<int> vis(vtot + 1);
        queue<int> q;
        q.push(s);
        vis[s] = 1;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int i = head[u]; i != -1; i = e[i].nxt)
                if (e[i].f > 0 && !vis[e[i].v]) {
                    vis[e[i].v] = 1;
                    q.push(e[i].v);
                }
        }
        return vis;
    }
};
struct BoundedFlow {
    static constexpr int INF = 4000000000000000000LL;
    struct edge {
        int u, v, l, r, id;
    };
    int n, S, T;
    vector<int> balance;
    vector<edge> edges;
    FlowGraph<int> g;
    vector<int> aux;
    BoundedFlow(int n = 0) {
        init(n);
    }
    void init(int n_) {
        n = n_;
        S = n + 1;
        T = n + 2;
        balance.assign(n + 1, 0);
        edges.clear();
        aux.clear();
        g.init(S, T, T);
    }
    int add_edge(int u, int v, int l, int r) {
        assert(0 <= l && l <= r);
        int id = g.etot;
        g.addedge(u, v, r - l);
        balance[u] -= l;
        balance[v] += l;
        edges.push_back({u, v, l, r, id});
        return edges.size() - 1;
    }
    bool feasible() {
        int need = 0;
        for (int u = 1; u <= n; u++) {
            if (balance[u] > 0) {
                aux.push_back(g.etot);
                g.addedge(S, u, balance[u]);
                need += balance[u];
            }
            if (balance[u] < 0) {
                aux.push_back(g.etot);
                g.addedge(u, T, -balance[u]);
            }
        }
        return g.dinic() == need;
    }
    int value(int k) {
        auto z = edges[k];
        return z.r - g.e[z.id].f;
    }
    optional<int> maxflow(int s, int t) {
        int back = g.etot;
        g.addedge(t, s, INF);
        if (!feasible())
            return nullopt;
        int base = g.e[back ^ 1].f;
        g.e[back].f = g.e[back ^ 1].f = 0;
        for (int id : aux)
            g.e[id].f = g.e[id ^ 1].f = 0;
        g.s = s;
        g.t = t;
        return base + g.dinic();
    }
};

