void solve() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m));
    int total = 0;
    for (auto &row : a)
        for (int &x : row) {
            cin >> x;
            total += x;
        }
    int s = n * m + 1, t = s + 1;
    FlowGraph<int> g;
    g.init(s, t, t);
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            int u = i * m + j + 1;
            if ((i + j) % 2 == 0) {
                g.addedge(s, u, a[i][j]);
                for (int k = 0; k < 4; k++) {
                    int x = i + dx[k], y = j + dy[k];
                    if (0 <= x && x < n && 0 <= y && y < m)
                        g.addedge(u, x * m + y + 1, total + 1);
                }
            } else
                g.addedge(u, t, a[i][j]);
        }
    cout << total - g.dinic() << '\n';
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t = 1;
    // cin >> t;
    while (t--)
        solve();
    return 0;
}

