void solve() {
    int m, n;
    cin >> m >> n;
    string line;
    getline(cin, line);
    vector<int> profit(m + 1);
    vector<vector<int>> need(m + 1);
    int total = 0;
    for (int i = 1; i <= m; i++) {
        getline(cin, line);
        istringstream in(line);
        in >> profit[i];
        total += profit[i];
        int x;
        while (in >> x)
            need[i].push_back(x);
    }
    vector<int> cost(n + 1);
    for (int j = 1; j <= n; j++)
        cin >> cost[j];
    int s = m + n + 1, t = s + 1;
    FlowGraph<int> g;
    g.init(s, t, t);
    for (int i = 1; i <= m; i++) {
        g.addedge(s, i, profit[i]);
        for (int j : need[i])
            g.addedge(i, m + j, total + 1);
    }
    for (int j = 1; j <= n; j++)
        g.addedge(m + j, t, cost[j]);
    int ans = total - g.dinic();
    auto vis = g.cut_side();
    for (int i = 1; i <= m; i++)
        if (vis[i])
            cout << i << ' ';
    cout << '\n';
    for (int j = 1; j <= n; j++)
        if (vis[m + j])
            cout << j << ' ';
    cout << '\n' << ans << '\n';
}

