    int etot; // 已存残量边数，等于e.size()，始终偶数；边号须在int范围内；init清0。
    // head：一维vector，init分配vtot+1项，下标1..vtot；邻接链首边编号，-1为空；init置-1。
    vector<int> head;
    // dis：一维vector，init分配vtot+1项并清0；下标1..vtot；BFS层数，0未访问，源为1；DFS死点置-1；每次bfs清0。
    vector<int> dis;
