    // init执行e.clear并令etot=0；addedge成对push_back，不提前resize占用边号。
    vector<edge> e;

    // init(s_,t_,vtot_)：设置源汇与点数；返回void；清边数与邻接链。
    // 前提合法编号、s_!=t_，随后重新建图；首次时间O(vtot_)；重建还包括清除旧边。
    void init(int s_, int t_, int vtot_) {
        s = s_;
        t = t_;
        vtot = vtot_;
        etot = 0; // 多次建图必须清etot。
        head.assign(vtot + 1, -1);
