    // 前提u/v=1..vtot，f>=0，边号及etot不溢出int；原容量需另存时由调用方记录。
    void addedge(int u, int v, T f) {
        e.push_back({v, head[u], f});
        head[u] = etot++;
        e.push_back({u, head[v], 0});
        head[v] = etot++;
