                int nf = max(f, g) + dp[u][0], ng = f == -INF ? -INF : f + dp[u][1];
                f = nf;
                g = ng;
            }
            best = max(best, first ? f : max(f, g));
        }
        ans += best;
    }
    return ans;
}

void init_model(int n = 0) {
    init(n);
}

void solve() {
    int n;
    cin >> n;
    ::init_model(n);
    for (int i = 1; i <= n; i++)
        cin >> ::val[i];
    vector<array<int, 3>> e(n);
    for (auto &z : e) {
        cin >> z[0] >> z[1];
        z[0]++;
        z[1]++;
        z[2] = 0;
    }
    long double k;
    cin >> k;
    ::orient(e);
    cout << fixed << setprecision(1) << ::run() * k << '\n';
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t = 1;
    // cin >> t;
    while (t--)
        solve();
    return 0;
}

