            dfs(u);
            a.push_back(d[u]);
            b.push_back(w[u]);
        }
        ans += max(inside, ring_path(a, b));
    }
    return ans;
}
struct info {
    int minus, plus, best;
};
info merge(info a, info b) {
    return {max(a.minus, b.minus), max(a.plus, b.plus),
            max({a.best, b.best, a.minus + b.plus})};
}
