    int n, lg, timer;
    vector<vector<int>> e;
    vector<vector<info>> path;
    vector<int> fa, dep, l, r, dp, sdp, bit;
    vector<vector<int32_t>> up;
    TreePathSelect(int n = 0) {
        init(n);
    }
    void init(int n_) {
        n = n_;
        lg = 1;
        while ((1LL << lg) <= n)
            lg++;
        timer = 0;
        e.assign(n + 1, {});
        path.assign(n + 1, {});
        fa.assign(n + 1, 0);
        dep = fa;
        l = fa;
        r = fa;
        dp = fa;
        sdp = fa;
        bit.assign(n + 2, 0);
        up.assign(lg, vector<int32_t>(n + 1));
    }
    void add_edge(int u, int v) {
        e[u].push_back(v);
        e[v].push_back(u);
    }
    void build(int u, int p) {
        fa[u] = p;
        dep[u] = dep[p] + 1;
        l[u] = ++timer;
        up[0][u] = p;
        for (int k = 1; k < lg; k++)
            up[k][u] = up[k - 1][up[k - 1][u]];
        for (int v : e[u])
            if (v != p)
                build(v, u);
        r[u] = timer;
    }
    void build(int root = 1) {
        timer = 0;
        build(root, 0);
    }
    int lca(int x, int y) {
        if (dep[x] < dep[y])
            swap(x, y);
        int d = dep[x] - dep[y];
        for (int k = 0; k < lg; k++)
            if (d >> k & 1)
                x = up[k][x];
        if (x == y)
            return x;
        for (int k = lg - 1; k >= 0; k--)
            if (up[k][x] != up[k][y]) {
                x = up[k][x];
                y = up[k][y];
            }
        return fa[x];
    }
    void add_path(int x, int y, int w) {
        path[lca(x, y)].push_back({x, y, w});
    }
    void change(int x, int v) {
        for (; x <= n + 1; x += x & -x)
            bit[x] += v;
    }
    int qur(int x) {
        int ans = 0;
        for (; x; x -= x & -x)
            ans += bit[x];
        return ans;
    }
