void solve() {
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        AncestorCover t(n);
        vector<int> fa(n + 1), used(n + 1);
        int root = 0;
        for (int u = 1; u <= n; u++) {
            cin >> fa[u];
            if (fa[u] == u)
                root = u;
            else
                t.add_edge(fa[u], u);
        }
        t.build(root);
        for (int u = 1; u <= n; u++)
            if (t.son[u].empty())
                t.add_path(u, root, 1);
        cout << t.run_heap(root) << '\n';
        for (int u = 1; u <= n; u++)
            if (t.son[u].empty()) {
                vector<int> p;
                int v = u;
                while (!used[v]) {
                    p.push_back(v);
                    used[v] = 1;
                    if (v == root)
                        break;
                    v = fa[v];
                }
                reverse(p.begin(), p.end());
                cout << p.size() << '\n';
                for (int x : p)
                    cout << x << ' ';
                cout << '\n';
            }
        cout << '\n';
    }
}

