// 前缀关系计数：把满足条件的区间转为两个前缀的相同键值，按顺序统计此前相同前缀数。
// n次add期望O(n)时间/O(n)空间；unordered_map最坏可O(n²)。
struct PrefixPairs {
    unordered_map<int, int> cnt;
    int ans = 0;
    void init(int reserve_n = 0) {
        cnt.clear();
        cnt.reserve(reserve_n * 2 + 1);
        ans = 0;
    }
    int add(int key) {
        int old = cnt[key];
        ans += old;
        cnt[key]++;
        return old;
    }
};

