                p[i * x] = x;
                if (i % x == 0) {
                    h[i * x] = mul(h[i], x);
                    break;
                }
                h[i * x] = mul(h[i], norm(x * (1 - x)));
            }
        }
        for (int i = 1; i <= n; i++)
            pre[i] = (pre[i - 1] + h[i]) % mod;
    }
    int qur(int a, int b) {
