    int maximum(int a, int b) {
        assert(a > 0 && b > 0 && std::gcd(a, b) == 1);
        __int128 z = (__int128)a * b - a - b;
        assert(z <= LLONG_MAX);
        return z;
    }
    int count(int a, int b) {
        assert(a > 0 && b > 0 && std::gcd(a, b) == 1);
        __int128 z = (__int128)(a - 1) * (b - 1) / 2;
        assert(z <= LLONG_MAX);
        return z;
    }
};

