struct Solution {
    vector<double> medianSlidingWindow(vector<int32_t> &nums, int32_t k) {
        Mid t;
        vector<double> ans;
        for (int i = 0; i < (int)nums.size(); i++) {
            t.add(nums[i]);
            if (i >= k)
                t.del(nums[i - k]);
            if (i + 1 >= k) {
                double z = t.mid();
                if (k % 2 == 0)
                    z = (z + (double)*t.R.begin()) / 2;
                ans.push_back(z);
            }
        }
        return ans;
    }
};
void solve() {
    int n;
    int32_t k;
    cin >> n >> k;
    vector<int32_t> a(n);
    for (auto &x : a)
        cin >> x;
    Solution s;
    auto ans = s.medianSlidingWindow(a, k);
    for (double x : ans)
        cout << setprecision(10) << x << ' ';
    cout << '\n';
}

