    pair<int, int> mx1 = {-1, 0}, mx2 = {-1, 0};
    for (int v : e[u])
        if (v != fa) {
            dfs(v, u);
            sum += f[v];
            best = max(best, a[v]);
            if (t[v] == 3) {
                pair<int, int> z = {a[v], v};
                if (z > mx1) {
